 G('Adjective position',['Regra','Exemplo'],[['antes do substantivo','**a red car**'],['depois de be','**The car is red.**'],['sem plural','**red cars**'],['ordem','**a nice big red car**']],'Ordem: **opinião → tamanho → cor → origem → material**.','Não coloque o adjetivo depois: *a car red* ✗.'),
 [('I have ___ car. (red/a red)','a red','antes.',None),('The car ___ red. (be)','is','be.',None),('Two ___ cars. (reds/red)','red','sem plural.',None),('A ___ big car. (nice)','nice','opinião.',None)],
 ['adjective;adjetivo;An adjective.;Um adjetivo.','noun;substantivo;A noun.;Um substantivo.','order;ordem;Word order.;Ordem das palavras.','size;tamanho;Its size.;O tamanho.','nice;legal;A nice car.;Um carro legal.','big;grande;A big house.;Uma casa grande.','small;pequeno;A small box.;Uma caixa pequena.','color;cor;What color?;Qual cor?'],
 ('Describing',[('Ana','What kind of car do you have?','Que tipo de carro?'),('Leo','A small red car.','Um carro pequeno e vermelho.'),('Ana','Is it new?','É novo?'),('Leo','Yes, it’s a nice new car.','Sim, é um carro novo e legal.')]),
